#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/mise/tasks/updateall-configs.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Render the selected Mac tools of bootstrap into $HOME"
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--dry-run" help="show the changes without writing them"
# USAGE flag "--no-bootstrap" help="skip the mise bootstrap of a first setup"
# USAGE flag "--verbose" help="list each file, also an unchanged one"

# `bootstrap mac sync` fetches the bootstrap clone into ~/.cache/bootstrap/,
# examines its version and syncs the Mac from ~/.config/bootstrap/macos.toml.
# BOOTSTRAP_BIN, a local build, replaces the bootstrap of mise.
#
# The task is standalone: it imports no library, so it runs before the first
# sync writes one. It runs under mise run and directly, with uv on PATH.

import os
import re
import shutil
import subprocess
import sys

USAGE = """\
usage: mise run updateall:configs [--dry-run] [--no-bootstrap] [--verbose]

  --dry-run       show the changes without writing them
  --no-bootstrap  skip the mise bootstrap of a first setup
  --verbose       list each file, also an unchanged one
  -h, --help      show this help

exit codes: 0 done, 1 other failure, 2 usage or config error, 3 a tool
that bootstrap does not have, 4 open a new terminal (after a first setup,
or when a script asks for it), 5 the clone or fetch failed
"""


def styled():
  """True when the output on stderr shows glyphs. The rule of style_enabled
  of helpers."""
  force = os.environ.get("FORCE_COLOR", "")
  if force and force != "0":
    return True
  if os.environ.get("NO_COLOR", ""):
    return False
  try:
    tty = os.isatty(2)
  except OSError:
    tty = False
  return tty and (os.environ.get("TERM") or "dumb") != "dumb"


def log(msg):
  """An info line: a glyph when styled, else [INFO]."""
  print(f"· {msg}" if styled() else f"[INFO] {msg}", file=sys.stderr, flush=True)


def log_error(msg):
  """An error line: a glyph when styled, else [ERROR]."""
  print(f"✗ {msg}" if styled() else f"[ERROR] {msg}", file=sys.stderr, flush=True)


def env(name):
  """The value of the variable, or None when it is unset or empty, as
  ${name:-} of the shell."""
  return os.environ.get(name) or None


def parse_args(argv):
  """The flags come from sys.argv, never from mise's usage_* variables, so the
  task works the same under `mise run` and directly. The task consumes
  --verbose: it exports BOOTSTRAP_VERBOSE=1 and does not pass the flag on.
  Returns the flags for bootstrap, in their order."""
  args = []
  for arg in argv:
    if arg in ("--dry-run", "--no-bootstrap"):
      args.append(arg)
    elif arg == "--verbose":
      os.environ["BOOTSTRAP_VERBOSE"] = "1"
    elif arg in ("-h", "--help"):
      sys.stdout.write(USAGE)
      sys.exit(0)
    else:
      log_error(f"unknown flag '{arg}'")
      sys.stderr.write(USAGE)
      sys.exit(2)
  return args


def legacy_cleanup():
  """The cache of the old Mac sync. Its list of generated files moves to the
  new cache, when that cache has no list, so the stale rule removes the old
  files. The old folder then goes, but not while the old Mac sync holds its
  lock: a later run removes it. A failure here is not an error of the sync,
  and a list that cannot move keeps the old folder."""
  cache_home = env("XDG_CACHE_HOME") or f"{os.environ['HOME']}/.cache"
  cache = env("BOOTSTRAP_CACHE") or f"{cache_home}/bootstrap"
  old = f"{cache_home}/macos-setup"
  manifest = f"{cache}/macos-generated.tsv"
  if not os.path.exists(old):
    return
  try:
    os.makedirs(cache, exist_ok=True)
  except OSError as e:
    # mkdir -p of the shell task stopped the task with code 1.
    print(f"mkdir: {cache}: {e.strerror}", file=sys.stderr, flush=True)
    sys.exit(1)
  if not os.path.exists(manifest) and os.path.isfile(f"{old}/generated.txt"):
    try:
      shutil.move(f"{old}/generated.txt", manifest)
    except OSError:
      log_error(f"cannot move {old}/generated.txt to {manifest}: keeping {old}")
      return
  try:
    with open(f"{old}/lock/pid", encoding="utf-8", errors="surrogateescape") as f:
      pid = f.read().rstrip("\n")
  except OSError:
    pid = ""
  if re.fullmatch(r"[0-9]+", pid):
    try:
      os.kill(int(pid), 0)
      alive = True
    except (OSError, OverflowError):
      alive = False
    if alive:
      log(f"the old Mac sync runs (pid {pid}): keeping {old}")
      return
  try:
    if os.path.isdir(old) and not os.path.islink(old):
      shutil.rmtree(old, ignore_errors=True)
    else:
      os.remove(old)
  except OSError:
    pass


def main():
  args = parse_args(sys.argv[1:])

  if env("_UPDATEALL_CONFIGS_RUNNING"):
    log_error("updateall:configs is already running in this process tree: a nested run is refused")
    sys.exit(2)
  os.environ["_UPDATEALL_CONFIGS_RUNNING"] = "1"

  # A git hook exports these, and the clone of bootstrap must not follow them.
  for name in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE"):
    os.environ.pop(name, None)

  legacy_cleanup()

  # The exit code of bootstrap is the exit code of this task, exit 4 (open a
  # new terminal) too.
  engine = env("BOOTSTRAP_BIN") or "bootstrap"
  try:
    rc = subprocess.run([engine, "mac", "sync", *args], check=False).returncode
  except OSError as e:
    # The codes of the shell for a command that it cannot find or run.
    print(f"{engine}: {e.strerror}", file=sys.stderr, flush=True)
    rc = 127 if isinstance(e, FileNotFoundError) else 126
  sys.exit(128 - rc if rc < 0 else rc)


if __name__ == "__main__":
  main()
